import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.some.js";
import "core-js/modules/web.url-search-params.delete.js";
import "core-js/modules/web.url-search-params.has.js";
import "core-js/modules/web.url-search-params.size.js";
// 导入世界设置JSON数据
import worldSettingsData from '../../../dist/misc/dst_world_setting.json';
// 导入世界配置工具函数
import { initWorldCategorySettings, getWorldCategories, getSortedCategoryKeys, getSortedItemKeys, createWorldConfig, getItemImageStyle } from '../../utils/worldConfigUtils';
export default {
  name: 'WorldSettings',
  data() {
    return {
      loading: false,
      previewLoading: false,
      previewVisible: false,
      previewData: null,
      isEdit: false,
      saveId: null,
      // 存档基本信息
      saveForm: {
        name: '',
        description: ''
      },
      // 验证规则
      saveRules: {
        name: [{
          required: true,
          message: '请输入存档名称',
          trigger: 'blur'
        }, {
          min: 2,
          max: 30,
          message: '长度在 2 到 30 个字符',
          trigger: 'blur'
        }]
      },
      // 世界列表
      worlds: [],
      // 世界设置数据
      worldSettingsData: worldSettingsData,
      // 当前操作状态
      currentAction: null,
      // 错误信息
      errorMessage: '',
      errorVisible: false,
      // 导入导出
      importDialogVisible: false,
      importContent: '',
      importLoading: false,
      // 批量操作
      batchDrawerVisible: false,
      batchSelectedWorlds: [],
      batchOperationType: 'worldgen',
      batchLoading: false
    };
  },
  computed: {
    // 是否已有森林世界
    hasForestWorld() {
      return this.worlds.some(world => world.type === 'master');
    },
    // 是否已有洞穴世界
    hasCaveWorld() {
      return this.worlds.some(world => world.type === 'cave');
    }
  },
  methods: {
    // 返回列表页
    goBack() {
      this.$router.push('/worlds/list');
    },
    // 保存设置
    saveSettings() {
      this.$refs.saveForm.validate(valid => {
        if (valid) {
          if (this.worlds.length === 0) {
            this.showError('请至少添加一个世界');
            return;
          }
          this.loading = true;
          this.currentAction = 'saving';

          // 准备保存的数据
          const saveData = {
            ...this.saveForm,
            worlds: this.worlds.map(world => {
              // 仅保存必要的数据，不包括UI状态等
              return {
                name: world.name,
                type: world.type,
                worldgen: world.worldgen,
                worldsettings: world.worldsettings,
                mods: world.mods,
                others: world.others
              };
            })
          };
          console.log('保存的数据:', saveData);

          // 模拟API调用
          setTimeout(() => {
            this.loading = false;
            this.currentAction = null;

            // 随机模拟错误情况，便于测试
            if (Math.random() > 0.8) {
              this.showError('保存失败，请稍后重试');
            } else {
              this.$message({
                message: this.isEdit ? '存档设置已更新' : '存档创建成功',
                type: 'success'
              });
              this.goBack();
            }
          }, 1000);
        } else {
          this.showError('请正确填写表单信息');
          return false;
        }
      });
    },
    // 添加世界
    addWorld(type) {
      // 使用工具函数创建新世界的初始数据结构
      const newWorld = createWorldConfig(type, type === 'master' ? '森林世界' : '洞穴世界', this.worldSettingsData);

      // 添加搜索和重置状态
      newWorld.worldgenSearch = '';
      newWorld.worldsettingsSearch = '';
      newWorld.worldgenResetting = false;
      newWorld.worldsettingsResetting = false;
      this.worlds.push(newWorld);
    },
    // 删除世界
    removeWorld(index) {
      this.$confirm('确定要删除此世界吗?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.worlds.splice(index, 1);
        this.$message({
          type: 'success',
          message: '删除成功!'
        });
      }).catch(() => {});
    },
    // 获取世界生成分类
    getWorldgenCategories(worldType) {
      const mappedType = worldType === 'master' ? 'forest' : 'cave';
      return getWorldCategories(this.worldSettingsData, mappedType, 'WORLDGEN_GROUP');
    },
    // 获取世界设置分类
    getWorldsettingsCategories(worldType) {
      const mappedType = worldType === 'master' ? 'forest' : 'cave';
      return getWorldCategories(this.worldSettingsData, mappedType, 'WORLDSETTINGS_GROUP');
    },
    // 获取排序后的分类键数组
    getSortedCategoryKeys(categories) {
      return getSortedCategoryKeys(categories);
    },
    // 获取排序后的项目键数组
    getSortedItemKeys(items) {
      return getSortedItemKeys(items);
    },
    // 获取配置项的图片样式
    getItemImageStyle(item, isWorldgen = true) {
      const atlasPath = isWorldgen ? '/dist/misc/worldgen_customization.webp' : '/dist/misc/worldsettings_customization.webp';
      return getItemImageStyle(item, atlasPath);
    },
    // 加载存档数据
    loadSaveData() {
      if (!this.saveId) return;
      this.loading = true;

      // 模拟API调用
      setTimeout(() => {
        // 模拟从API获取的数据
        const saveData = {
          id: 1,
          name: '测试存档',
          description: '这是一个测试存档',
          worlds: [{
            name: '森林世界',
            type: 'master'
            // 其他数据...
          }, {
            name: '洞穴世界',
            type: 'cave'
            // 其他数据...
          }]
        };

        // 设置表单数据
        this.saveForm.name = saveData.name;
        this.saveForm.description = saveData.description;

        // 设置世界数据
        this.worlds = saveData.worlds.map(world => {
          // 使用映射类型
          const mappedType = world.type === 'master' ? 'forest' : 'cave';
          return {
            ...world,
            activeTab: 'basic',
            worldgen: world.worldgen || initWorldCategorySettings(this.worldSettingsData, mappedType, 'WORLDGEN_GROUP'),
            worldsettings: world.worldsettings || initWorldCategorySettings(this.worldSettingsData, mappedType, 'WORLDSETTINGS_GROUP'),
            mods: world.mods || {},
            others: world.others || {}
          };
        });
        this.loading = false;
      }, 1000);
    },
    // 预览设置
    previewSettings() {
      this.$refs.saveForm.validate(valid => {
        if (valid) {
          if (this.worlds.length === 0) {
            this.$message.error('请至少添加一个世界');
            return;
          }
          this.previewLoading = true;
          this.previewVisible = true;

          // 准备预览数据
          this.previewData = {
            ...this.saveForm,
            worlds: this.worlds.map(world => ({
              name: world.name,
              type: world.type,
              worldgen: world.worldgen,
              worldsettings: world.worldsettings
            }))
          };

          // 模拟加载延迟
          setTimeout(() => {
            this.previewLoading = false;
          }, 500);
        } else {
          this.$message.error('请正确填写表单信息');
          return false;
        }
      });
    },
    // 获取预览表格数据
    getPreviewTableData(settings) {
      const result = [];
      Object.entries(settings).forEach(([categoryKey, category]) => {
        Object.entries(category).forEach(([itemKey, value]) => {
          result.push({
            category: this.getCategoryText(categoryKey),
            item: this.getItemText(categoryKey, itemKey),
            value: this.getOptionText(categoryKey, itemKey, value)
          });
        });
      });
      return result;
    },
    // 获取分类文本
    getCategoryText(categoryKey) {
      const categories = {
        ...this.getWorldgenCategories('master'),
        ...this.getWorldsettingsCategories('master')
      };
      return categories[categoryKey]?.text || categoryKey;
    },
    // 获取项目文本
    getItemText(categoryKey, itemKey) {
      const categories = {
        ...this.getWorldgenCategories('master'),
        ...this.getWorldsettingsCategories('master')
      };
      return categories[categoryKey]?.items[itemKey]?.text || itemKey;
    },
    // 获取选项文本
    getOptionText(categoryKey, itemKey, value) {
      const categories = {
        ...this.getWorldgenCategories('master'),
        ...this.getWorldsettingsCategories('master')
      };
      return categories[categoryKey]?.items[itemKey]?.desc[value] || value;
    },
    // 判断分类是否应该显示（基于搜索关键词）
    isCategoryVisible(category, searchTerm) {
      if (!searchTerm) return true;
      const searchLower = searchTerm.toLowerCase();

      // 检查分类名称
      if (category.text.toLowerCase().includes(searchLower)) return true;

      // 检查分类下的所有项目
      for (const key in category.items) {
        const item = category.items[key];
        if (item.text.toLowerCase().includes(searchLower)) return true;
      }
      return false;
    },
    // 判断项目是否应该显示（基于搜索关键词）
    isItemVisible(item, searchTerm) {
      if (!searchTerm) return true;
      const searchLower = searchTerm.toLowerCase();
      return item.text.toLowerCase().includes(searchLower);
    },
    // 重置世界生成配置为默认值
    resetWorldgenToDefault(world) {
      this.$confirm('确定要将世界生成配置恢复为默认值吗？此操作不可逆！', '警告', {
        confirmButtonText: '确定恢复',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        world.worldgenResetting = true;

        // 模拟API调用延迟
        setTimeout(() => {
          const mappedType = world.type === 'master' ? 'forest' : 'cave';
          world.worldgen = initWorldCategorySettings(this.worldSettingsData, mappedType, 'WORLDGEN_GROUP');
          world.worldgenResetting = false;
          this.$message({
            type: 'success',
            message: '世界生成配置已恢复默认值'
          });
        }, 500);
      }).catch(() => {});
    },
    // 重置世界设置配置为默认值
    resetWorldsettingsToDefault(world) {
      this.$confirm('确定要将世界设置配置恢复为默认值吗？此操作不可逆！', '警告', {
        confirmButtonText: '确定恢复',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        world.worldsettingsResetting = true;

        // 模拟API调用延迟
        setTimeout(() => {
          const mappedType = world.type === 'master' ? 'forest' : 'cave';
          world.worldsettings = initWorldCategorySettings(this.worldSettingsData, mappedType, 'WORLDSETTINGS_GROUP');
          world.worldsettingsResetting = false;
          this.$message({
            type: 'success',
            message: '世界设置配置已恢复默认值'
          });
        }, 500);
      }).catch(() => {});
    },
    // 显示错误消息
    showError(message) {
      this.$message({
        message: message,
        type: 'error',
        duration: 3000
      });
    },
    // 模拟处理保存错误
    handleSaveError(error) {
      console.error('保存错误:', error);
      this.showError('保存失败: ' + (error.message || '未知错误'));
      this.loading = false;
      this.currentAction = null;
    },
    // 处理导入导出
    handleExportImport(command) {
      if (command === 'export') {
        this.exportConfig();
      } else if (command === 'import') {
        this.importDialogVisible = true;
      }
    },
    // 导出配置
    exportConfig() {
      try {
        // 准备导出的数据
        const exportData = {
          saveForm: this.saveForm,
          worlds: this.worlds.map(world => ({
            name: world.name,
            type: world.type,
            worldgen: world.worldgen,
            worldsettings: world.worldsettings
          }))
        };

        // 将数据转换为JSON字符串
        const jsonStr = JSON.stringify(exportData, null, 2);

        // 创建Blob对象
        const blob = new Blob([jsonStr], {
          type: 'application/json'
        });

        // 创建下载链接
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `${this.saveForm.name || 'world_config'}_${new Date().toISOString().split('T')[0]}.json`;

        // 触发下载
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        this.$message({
          message: '配置已导出',
          type: 'success'
        });
      } catch (error) {
        console.error('导出错误:', error);
        this.showError('导出失败: ' + (error.message || '未知错误'));
      }
    },
    // 导入配置
    importConfig() {
      if (!this.importContent.trim()) {
        this.showError('请输入有效的配置内容');
        return;
      }
      this.importLoading = true;
      setTimeout(() => {
        try {
          // 解析JSON数据
          const importData = JSON.parse(this.importContent);

          // 验证数据格式
          if (!importData.saveForm || !importData.worlds || !Array.isArray(importData.worlds)) {
            throw new Error('配置格式无效');
          }

          // 更新表单数据
          this.saveForm = importData.saveForm;

          // 更新世界数据
          this.worlds = importData.worlds.map(world => {
            const mappedType = world.type === 'master' ? 'forest' : 'cave';

            // 创建完整的世界对象
            return {
              name: world.name,
              type: world.type,
              activeTab: 'basic',
              worldgen: world.worldgen || initWorldCategorySettings(this.worldSettingsData, mappedType, 'WORLDGEN_GROUP'),
              worldsettings: world.worldsettings || initWorldCategorySettings(this.worldSettingsData, mappedType, 'WORLDSETTINGS_GROUP'),
              mods: world.mods || {},
              others: world.others || {},
              worldgenSearch: '',
              worldsettingsSearch: '',
              worldgenResetting: false,
              worldsettingsResetting: false
            };
          });
          this.$message({
            message: '配置导入成功',
            type: 'success'
          });
          this.importDialogVisible = false;
          this.importContent = '';
        } catch (error) {
          console.error('导入错误:', error);
          this.showError('导入失败: ' + (error.message || '配置格式无效'));
        } finally {
          this.importLoading = false;
        }
      }, 500);
    },
    // 批量恢复默认值
    batchResetToDefault() {
      if (this.batchSelectedWorlds.length === 0) {
        this.showError('请选择至少一个世界');
        return;
      }
      const operationType = this.batchOperationType;
      const operationName = operationType === 'worldgen' ? '世界生成配置' : '世界设置配置';
      const groupType = operationType === 'worldgen' ? 'WORLDGEN_GROUP' : 'WORLDSETTINGS_GROUP';
      this.$confirm(`确定要将选中世界的${operationName}批量恢复为默认值吗？此操作不可逆！`, '警告', {
        confirmButtonText: '确定恢复',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        this.batchLoading = true;

        // 模拟API调用延迟
        setTimeout(() => {
          // 对每个选中的世界执行恢复操作
          this.batchSelectedWorlds.forEach(index => {
            const world = this.worlds[index];
            const mappedType = world.type === 'master' ? 'forest' : 'cave';
            world[operationType] = initWorldCategorySettings(this.worldSettingsData, mappedType, groupType);
          });
          this.batchLoading = false;
          this.$message({
            type: 'success',
            message: `已成功将 ${this.batchSelectedWorlds.length} 个世界的${operationName}恢复为默认值`
          });

          // 清空选择
          this.batchSelectedWorlds = [];
          this.batchDrawerVisible = false;
        }, 1000);
      }).catch(() => {});
    }
  },
  created() {
    // 判断是否为编辑模式
    const {
      id
    } = this.$route.query;
    if (id) {
      this.isEdit = true;
      this.saveId = parseInt(id);
      this.loadSaveData();
    } else {
      // 默认添加一个森林世界
      this.addWorld('master');
    }
  }
};
